{
  "wireMagic": "pb3",
  "pens": [ {

  } ],
  "wsWinStyles": [ {

  } ],
  "wpWinPositions": [ {

  } ],
  "events": [ {
    "tStartMs": 1718,
    "dDurationMs": 1051,
    "segs": [ {
      "utf8": "但是我的意思就是說"
    } ]
  }, {
    "tStartMs": 5372,
    "dDurationMs": 1951,
    "segs": [ {
      "utf8": "就是因為我覺得火鍋的特色就是"
    } ]
  }, {
    "tStartMs": 11428,
    "dDurationMs": 1017,
    "segs": [ {
      "utf8": "我們不會說一個人"
    } ]
  }, {
    "tStartMs": 13646,
    "dDurationMs": 1068,
    "segs": [ {
      "utf8": "但每一個人都會有"
    } ]
  }, {
    "tStartMs": 16566,
    "dDurationMs": 951,
    "segs": [ {
      "utf8": "我的想法就是"
    } ]
  }, {
    "tStartMs": 20387,
    "dDurationMs": 1534,
    "segs": [ {
      "utf8": "就在描寫所謂的"
    } ]
  }, {
    "tStartMs": 25959,
    "dDurationMs": 1435,
    "segs": [ {
      "utf8": "然後我們好像被社會上"
    } ]
  }, {
    "tStartMs": 28561,
    "dDurationMs": 1452,
    "segs": [ {
      "utf8": "甚至我必須這麼說"
    } ]
  }, {
    "tStartMs": 30013,
    "dDurationMs": 1501,
    "segs": [ {
      "utf8": "連候選人推出來"
    } ]
  }, {
    "tStartMs": 33116,
    "dDurationMs": 867,
    "segs": [ {
      "utf8": "這一次又是"
    } ]
  }, {
    "tStartMs": 38471,
    "dDurationMs": 951,
    "segs": [ {
      "utf8": "各位觀眾朋友大家好 "
    } ]
  }, {
    "tStartMs": 39422,
    "dDurationMs": 1652,
    "segs": [ {
      "utf8": "我是旅行長工頭堅"
    } ]
  }, {
    "tStartMs": 41074,
    "dDurationMs": 1001,
    "segs": [ {
      "utf8": "我們這個頻道呢"
    } ]
  }, {
    "tStartMs": 42075,
    "dDurationMs": 1385,
    "segs": [ {
      "utf8": "之前曾經有一段時間"
    } ]
  }, {
    "tStartMs": 43460,
    "dDurationMs": 1001,
    "segs": [ {
      "utf8": "大家可能還記得"
    } ]
  }, {
    "tStartMs": 44461,
    "dDurationMs": 1201,
    "segs": [ {
      "utf8": "做過Podcast"
    } ]
  }, {
    "tStartMs": 45662,
    "dDurationMs": 1802,
    "segs": [ {
      "utf8": "對談等等的形式"
    } ]
  }, {
    "tStartMs": 47464,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "但後來因為自己真的太忙了"
    } ]
  }, {
    "tStartMs": 49466,
    "dDurationMs": 2402,
    "segs": [ {
      "utf8": "一直去日本取材出外景"
    } ]
  }, {
    "tStartMs": 51868,
    "dDurationMs": 1218,
    "segs": [ {
      "utf8": "所以停了一段時間"
    } ]
  }, {
    "tStartMs": 53086,
    "dDurationMs": 2869,
    "segs": [ {
      "utf8": "那最近我跟製作人就思考了一下"
    } ]
  }, {
    "tStartMs": 55955,
    "dDurationMs": 2386,
    "segs": [ {
      "utf8": "我們可能會恢復這種對談的形態"
    } ]
  }, {
    "tStartMs": 58341,
    "dDurationMs": 2469,
    "segs": [ {
      "utf8": "等於是恢復對談形態的第一集"
    } ]
  }, {
    "tStartMs": 60810,
    "dDurationMs": 2703,
    "segs": [ {
      "utf8": "我們請到一位非常特別的來賓"
    } ]
  }, {
    "tStartMs": 63513,
    "dDurationMs": 1001,
    "segs": [ {
      "utf8": "我待會再介紹他"
    } ]
  }, {
    "tStartMs": 64514,
    "dDurationMs": 1151,
    "segs": [ {
      "utf8": "我先跟大家講一下"
    } ]
  }, {
    "tStartMs": 65665,
    "dDurationMs": 1285,
    "segs": [ {
      "utf8": "我們今天要談什麼"
    } ]
  }, {
    "tStartMs": 66950,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "今天這個議題是說"
    } ]
  }, {
    "tStartMs": 68952,
    "dDurationMs": 1551,
    "segs": [ {
      "utf8": "《台北的天空》 這首歌 "
    } ]
  }, {
    "tStartMs": 70503,
    "dDurationMs": 1318,
    "segs": [ {
      "utf8": "很多人可能聽過"
    } ]
  }, {
    "tStartMs": 71821,
    "dDurationMs": 1352,
    "segs": [ {
      "utf8": "它是1985年的 "
    } ]
  }, {
    "tStartMs": 73173,
    "dDurationMs": 2235,
    "segs": [ {
      "utf8": "到今年已經41年了"
    } ]
  }, {
    "tStartMs": 75408,
    "dDurationMs": 1802,
    "segs": [ {
      "utf8": "然後林強的 《向前走》"
    } ]
  }, {
    "tStartMs": 77210,
    "dDurationMs": 3070,
    "segs": [ {
      "utf8": "1990年到今年已經36年了"
    } ]
  }, {
    "tStartMs": 80280,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "這40年來台北蓋了捷運 "
    } ]
  }, {
    "tStartMs": 82282,
    "dDurationMs": 834,
    "segs": [ {
      "utf8": "蓋了101"
    } ]
  }, {
    "tStartMs": 83116,
    "dDurationMs": 2152,
    "segs": [ {
      "utf8": "東區起來好像又沒落了"
    } ]
  }, {
    "tStartMs": 85268,
    "dDurationMs": 1552,
    "segs": [ {
      "utf8": "南港內湖整個都變了樣"
    } ]
  }, {
    "tStartMs": 86820,
    "dDurationMs": 2602,
    "segs": [ {
      "utf8": "可是我們要唱台北的時候"
    } ]
  }, {
    "tStartMs": 89422,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "我們還是要回去唱那兩首"
    } ]
  }, {
    "tStartMs": 91424,
    "dDurationMs": 2786,
    "segs": [ {
      "utf8": "所以我們今天要來探討一個問題"
    } ]
  }, {
    "tStartMs": 94210,
    "dDurationMs": 2519,
    "segs": [ {
      "utf8": "就是說在台北住了40年之後"
    } ]
  }, {
    "tStartMs": 96729,
    "dDurationMs": 1685,
    "segs": [ {
      "utf8": "我們到底算不算台北人"
    } ]
  }, {
    "tStartMs": 98414,
    "dDurationMs": 2853,
    "segs": [ {
      "utf8": "然後我們接下來要唱什麼樣的歌"
    } ]
  }, {
    "tStartMs": 101267,
    "dDurationMs": 1719,
    "segs": [ {
      "utf8": "今天這位來賓就是"
    } ]
  }, {
    "tStartMs": 102986,
    "dDurationMs": 3136,
    "segs": [ {
      "utf8": "台北市長候選人沈伯洋 教授"
    } ]
  }, {
    "tStartMs": 106122,
    "dDurationMs": 801,
    "segs": [ {
      "utf8": "大家好"
    } ]
  }, {
    "tStartMs": 106923,
    "dDurationMs": 1635,
    "segs": [ {
      "utf8": "Puma老師 "
    } ]
  }, {
    "tStartMs": 108558,
    "dDurationMs": 1652,
    "segs": [ {
      "utf8": "我應該叫你Puma老師"
    } ]
  }, {
    "tStartMs": 110210,
    "dDurationMs": 2702,
    "segs": [ {
      "utf8": "用這樣的Puma老師這個角度"
    } ]
  }, {
    "tStartMs": 112912,
    "dDurationMs": 501,
    "segs": [ {
      "utf8": "好"
    } ]
  }, {
    "tStartMs": 113413,
    "dDurationMs": 2602,
    "segs": [ {
      "utf8": "這個剛才我們一開始聊到的"
    } ]
  }, {
    "tStartMs": 116015,
    "dDurationMs": 2937,
    "segs": [ {
      "utf8": "就是說一些整個世代人的共同記憶"
    } ]
  }, {
    "tStartMs": 118952,
    "dDurationMs": 1718,
    "segs": [ {
      "utf8": "那我覺得在談這個"
    } ]
  }, {
    "tStartMs": 120670,
    "dDurationMs": 1952,
    "segs": [ {
      "utf8": "比較嚴肅的問題之前"
    } ]
  }, {
    "tStartMs": 122622,
    "dDurationMs": 2886,
    "segs": [ {
      "utf8": "我發現之前我看過你訪問的一些影片"
    } ]
  }, {
    "tStartMs": 125508,
    "dDurationMs": 1001,
    "segs": [ {
      "utf8": "有一個小細節"
    } ]
  }, {
    "tStartMs": 126509,
    "dDurationMs": 2569,
    "segs": [ {
      "utf8": "就是你的工作室都有放一些公仔"
    } ]
  }, {
    "tStartMs": 129078,
    "dDurationMs": 735,
    "segs": [ {
      "utf8": "喔 對"
    } ]
  }, {
    "tStartMs": 129813,
    "dDurationMs": 2168,
    "segs": [ {
      "utf8": "基本上你是一個動漫的愛好者"
    } ]
  }, {
    "tStartMs": 131981,
    "dDurationMs": 935,
    "segs": [ {
      "utf8": "那我今天為了這個"
    } ]
  }, {
    "tStartMs": 132916,
    "dDurationMs": 2252,
    "segs": [ {
      "utf8": "我還要把我那個私藏很久的"
    } ]
  }, {
    "tStartMs": 135168,
    "dDurationMs": 1134,
    "segs": [ {
      "utf8": "這個可能大家知道 "
    } ]
  }, {
    "tStartMs": 136302,
    "dDurationMs": 1519,
    "segs": [ {
      "utf8": "他叫超人力霸王"
    } ]
  }, {
    "tStartMs": 137821,
    "dDurationMs": 667,
    "segs": [ {
      "utf8": "但是對我來講 "
    } ]
  }, {
    "tStartMs": 138488,
    "dDurationMs": 1635,
    "segs": [ {
      "utf8": "他就叫ウルトラマン"
    } ]
  }, {
    "tStartMs": 140123,
    "dDurationMs": 2386,
    "segs": [ {
      "utf8": "他的出生日期跟我同一年"
    } ]
  }, {
    "tStartMs": 142509,
    "dDurationMs": 1501,
    "segs": [ {
      "utf8": "所以今年他是60週年"
    } ]
  }, {
    "tStartMs": 144010,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "然後還有這個是 "
    } ]
  }, {
    "tStartMs": 146012,
    "dDurationMs": 1602,
    "segs": [ {
      "utf8": "可能大家也很熟悉的"
    } ]
  }, {
    "tStartMs": 147614,
    "dDurationMs": 2185,
    "segs": [ {
      "utf8": "在台灣他叫做無敵鐵金剛"
    } ]
  }, {
    "tStartMs": 149799,
    "dDurationMs": 2519,
    "segs": [ {
      "utf8": "其實他就是魔神Z"
    } ]
  }, {
    "tStartMs": 152318,
    "dDurationMs": 1135,
    "segs": [ {
      "utf8": "マジンガーZ"
    } ]
  }, {
    "tStartMs": 153453,
    "dDurationMs": 967,
    "segs": [ {
      "utf8": "我也很喜歡"
    } ]
  }, {
    "tStartMs": 154420,
    "dDurationMs": 618,
    "segs": [ {
      "utf8": "很喜歡 "
    } ]
  }, {
    "tStartMs": 155038,
    "dDurationMs": 834,
    "segs": [ {
      "utf8": "我真的超愛"
    } ]
  }, {
    "tStartMs": 155872,
    "dDurationMs": 1351,
    "segs": [ {
      "utf8": "這一盒我買了之後"
    } ]
  }, {
    "tStartMs": 157223,
    "dDurationMs": 1318,
    "segs": [ {
      "utf8": "都捨不得把它組合起來"
    } ]
  }, {
    "tStartMs": 158541,
    "dDurationMs": 2269,
    "segs": [ {
      "utf8": "對 我有兩盒到現在都還沒有打開"
    } ]
  }, {
    "tStartMs": 160810,
    "dDurationMs": 868,
    "segs": [ {
      "utf8": "都當收藏品"
    } ]
  }, {
    "tStartMs": 161678,
    "dDurationMs": 333,
    "segs": [ {
      "utf8": "對"
    } ]
  }, {
    "tStartMs": 162011,
    "dDurationMs": 885,
    "segs": [ {
      "utf8": "然後後面這一張 "
    } ]
  }, {
    "tStartMs": 162896,
    "dDurationMs": 1418,
    "segs": [ {
      "utf8": "可能有些人也看過"
    } ]
  }, {
    "tStartMs": 164314,
    "dDurationMs": 1101,
    "segs": [ {
      "utf8": "初代鋼彈"
    } ]
  }, {
    "tStartMs": 165415,
    "dDurationMs": 2903,
    "segs": [ {
      "utf8": "第二集的原聲帶黑膠"
    } ]
  }, {
    "tStartMs": 168318,
    "dDurationMs": 2102,
    "segs": [ {
      "utf8": "秀完了這個收藏品之後 "
    } ]
  }, {
    "tStartMs": 170420,
    "dDurationMs": 1201,
    "segs": [ {
      "utf8": "我們要來聊一下"
    } ]
  }, {
    "tStartMs": 171621,
    "dDurationMs": 3570,
    "segs": [ {
      "utf8": "就是說過去你對這些事情的這種"
    } ]
  }, {
    "tStartMs": 175191,
    "dDurationMs": 2119,
    "segs": [ {
      "utf8": "種種的回憶跟連結"
    } ]
  }, {
    "tStartMs": 177310,
    "dDurationMs": 1451,
    "segs": [ {
      "utf8": "是怎麼樣建立起來的"
    } ]
  }, {
    "tStartMs": 178761,
    "dDurationMs": 2937,
    "segs": [ {
      "utf8": "我覺得應該跟我成長的過程 "
    } ]
  }, {
    "tStartMs": 181698,
    "dDurationMs": 817,
    "segs": [ {
      "utf8": "很有關係"
    } ]
  }, {
    "tStartMs": 182515,
    "dDurationMs": 1402,
    "segs": [ {
      "utf8": "因為我就是老台北人"
    } ]
  }, {
    "tStartMs": 183917,
    "dDurationMs": 2302,
    "segs": [ {
      "utf8": "我們家就是世世代代在這一邊"
    } ]
  }, {
    "tStartMs": 186219,
    "dDurationMs": 1318,
    "segs": [ {
      "utf8": "至少從我有記憶以來 "
    } ]
  }, {
    "tStartMs": 187537,
    "dDurationMs": 1151,
    "segs": [ {
      "utf8": "我是阿祖帶大"
    } ]
  }, {
    "tStartMs": 188688,
    "dDurationMs": 1235,
    "segs": [ {
      "utf8": "我是女的阿祖帶大"
    } ]
  }, {
    "tStartMs": 189923,
    "dDurationMs": 2185,
    "segs": [ {
      "utf8": "但我男的阿祖比較早就走了"
    } ]
  }, {
    "tStartMs": 192108,
    "dDurationMs": 868,
    "segs": [ {
      "utf8": "我沒有看過他"
    } ]
  }, {
    "tStartMs": 192976,
    "dDurationMs": 1034,
    "segs": [ {
      "utf8": "但是他以前是里長"
    } ]
  }, {
    "tStartMs": 194010,
    "dDurationMs": 1702,
    "segs": [ {
      "utf8": "但一直都在五分埔這邊"
    } ]
  }, {
    "tStartMs": 195712,
    "dDurationMs": 1001,
    "segs": [ {
      "utf8": "一直都在五分埔"
    } ]
  }, {
    "tStartMs": 196713,
    "dDurationMs": 1201,
    "segs": [ {
      "utf8": "所以我們家以前"
    } ]
  }, {
    "tStartMs": 197914,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "我爸爸有看過我們以前的照片"
    } ]
  }, {
    "tStartMs": 199916,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "以前在那邊沒有高樓大廈 是田"
    } ]
  }, {
    "tStartMs": 201918,
    "dDurationMs": 1702,
    "segs": [ {
      "utf8": "然後我們家就是一個三合院"
    } ]
  }, {
    "tStartMs": 203620,
    "dDurationMs": 2102,
    "segs": [ {
      "utf8": "然後旁邊是開一家𥴊仔店"
    } ]
  }, {
    "tStartMs": 205722,
    "dDurationMs": 2802,
    "segs": [ {
      "utf8": "𥴊仔店就是大家人潮聚集的地方"
    } ]
  }, {
    "tStartMs": 208524,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "買東西 打彈珠 "
    } ]
  }, {
    "tStartMs": 210526,
    "dDurationMs": 2186,
    "segs": [ {
      "utf8": "買沙士都在那一個地方"
    } ]
  }, {
    "tStartMs": 212712,
    "dDurationMs": 2402,
    "segs": [ {
      "utf8": "所以我覺得那個從我阿祖開始"
    } ]
  }, {
    "tStartMs": 215114,
    "dDurationMs": 2303,
    "segs": [ {
      "utf8": "我們在地的連結很深"
    } ]
  }, {
    "tStartMs": 217417,
    "dDurationMs": 1051,
    "segs": [ {
      "utf8": "然後我又是她帶大 "
    } ]
  }, {
    "tStartMs": 218468,
    "dDurationMs": 1251,
    "segs": [ {
      "utf8": "她幾乎每兩三天"
    } ]
  }, {
    "tStartMs": 219719,
    "dDurationMs": 2102,
    "segs": [ {
      "utf8": "就會帶我去市場一次"
    } ]
  }, {
    "tStartMs": 221821,
    "dDurationMs": 2503,
    "segs": [ {
      "utf8": "所以我那天應該是幾天前吧"
    } ]
  }, {
    "tStartMs": 224324,
    "dDurationMs": 1685,
    "segs": [ {
      "utf8": "我在永春市場掃街的時候"
    } ]
  }, {
    "tStartMs": 226009,
    "dDurationMs": 1401,
    "segs": [ {
      "utf8": "因為我以前都在永吉市場"
    } ]
  }, {
    "tStartMs": 227410,
    "dDurationMs": 1852,
    "segs": [ {
      "utf8": "然後我們遇到永吉市場的攤販"
    } ]
  }, {
    "tStartMs": 229262,
    "dDurationMs": 1051,
    "segs": [ {
      "utf8": "在跟我阿祖說謝謝"
    } ]
  }, {
    "tStartMs": 230313,
    "dDurationMs": 2402,
    "segs": [ {
      "utf8": "說阿祖以前常常到他的攤子買東西"
    } ]
  }, {
    "tStartMs": 232715,
    "dDurationMs": 601,
    "segs": [ {
      "utf8": "OK"
    } ]
  }, {
    "tStartMs": 233316,
    "dDurationMs": 918,
    "segs": [ {
      "utf8": "所以就是這種"
    } ]
  }, {
    "tStartMs": 234234,
    "dDurationMs": 1084,
    "segs": [ {
      "utf8": "我覺得有時候就是"
    } ]
  }, {
    "tStartMs": 235318,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "人跟這種土地的這種親近"
    } ]
  }, {
    "tStartMs": 237320,
    "dDurationMs": 2803,
    "segs": [ {
      "utf8": "是我小時候很熟悉的感覺"
    } ]
  }, {
    "tStartMs": 240123,
    "dDurationMs": 1334,
    "segs": [ {
      "utf8": "我覺得可能是因為這樣子"
    } ]
  }, {
    "tStartMs": 241457,
    "dDurationMs": 2620,
    "segs": [ {
      "utf8": "那我們剛剛講到阿宅的一些喜好"
    } ]
  }, {
    "tStartMs": 244077,
    "dDurationMs": 1034,
    "segs": [ {
